parameters.jsCode:
const saida = $('07 ??? Agente de Atendimento WhatsApp').first().json.output;

const dados = typeof saida === 'string'
  ? JSON.parse(saida.replace(/^```(?:json)?\s*|\s*```$/g, '').trim())
  : saida;

const telefone = String(
  $('05-Cadastrar Cliente no PostgreSQL').first().json.telefone
);

return {
  json: {
    telefone,
    response: dados.response,
    intent: dados.intent,
    sentiment: dados.sentiment,
    requires_human: dados.requires_human
  }
};

const hex = (length) =>
  Array.from(
    { length },
    () => Math.floor(Math.random() * 16).toString(16)
  ).join('');

const inicio = Date.now();
const fim = Date.now();

const trace = {
  resourceSpans: [{
    resource: {
      attributes: [{
        key: "service.name",
        value: {
          stringValue: "agente-atendimento-whatsapp"
        }
      }]
    },
    scopeSpans: [{
      scope: {
        name: "n8n-langfuse"
      },
      spans: [{
        traceId: hex(32),
        spanId: hex(16),
        name: "agente-atendimento-checkpoint",
        kind: 1,
        startTimeUnixNano: `${inicio}000000`,
        endTimeUnixNano: `${Math.max(fim, inicio + 1)}000000`,
        attributes: [{
          key: "langfuse.observation.type",
          value: {
            stringValue: "span"
          }
        }]
      }]
    }]
  }]
};

return [{
  json: {
    otlp: trace
  }
}];
